import gurobipy as gp
from gurobipy import GRB
options = []
gen_per_lot = {}
cost_per_lot = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    option = v['option']
    options.append(option)
    try:
        gen_per_lot[option] = float(v['gen_per_lot'])
        cost_per_lot[option] = float(v['cost_per_lot'])
    except Exception as e:
        raise ValueError(f'Missing or invalid data for option {option}: {e}')
if set(options) != set(gen_per_lot.keys()) or set(options) != set(cost_per_lot.keys()):
    raise ValueError('Mismatch in options and coefficient data.')
m = gp.Model('electricity_lot_purchase')
x = m.addVars(options, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((cost_per_lot[k] * x[k] for k in options)), GRB.MINIMIZE)
m.addConstr(gp.quicksum((gen_per_lot[k] * x[k] for k in options)) >= 200, name='demand')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')